INSERT INTO destinations(id,name,description,image_url,category,rating) VALUES (1,'Pura Uluwatu','Pura megah di atas tebing setinggi 70 meter dari permukaan laut. Tempat terbaik menonton sunset dan pertunjukan Kecak Dance.','/images/uluwatu.jpg','Temple',4.8);
INSERT INTO destinations(id,name,description,image_url,category,rating) VALUES (2,'Tegallalang Rice Terrace','Sawah terasering ikonik di Ubud dengan pemandangan hijau yang memukau. Spot foto instagramable populer.','/images/tegallalang.jpg','Nature',4.7);
INSERT INTO destinations(id,name,description,image_url,category,rating) VALUES (3,'Nusa Penida','Pulau eksotis dengan tebing dramatis Kelingking Beach dan air laut kristal yang jernih. Surga snorkeling.','/images/nusa-penida.jpg','Island',4.9);
INSERT INTO destinations(id,name,description,image_url,category,rating) VALUES (4,'Tanah Lot','Pura laut yang berdiri di atas batu karang di tengah laut. Sunset paling spektakuler di Bali.','/images/tanah-lot.jpg','Temple',4.8);
INSERT INTO destinations(id,name,description,image_url,category,rating) VALUES (5,'Pantai Kuta','Pantai legendaris dengan ombak sempurna untuk surfing pemula. Sunset dan nightlife yang meriah.','/images/kuta.jpg','Beach',4.5);
INSERT INTO destinations(id,name,description,image_url,category,rating) VALUES (6,'Pura Tirta Empul','Pura suci dengan mata air alami untuk ritual melukat (pembersihan spiritual) yang sakral.','/images/tegallalang.jpg','Temple',4.7);
